import { multipleClassNames } from "@/core/helpers";
import styles from "./input-helper-text.module.less";
import { motion } from "framer-motion";

type InputHelperTextProps = {
  /** The text to display as the helper text under a form field */
  helperText: string;
  contentfulLabelId?: string;
};

export const InputHelperText = ({ helperText, contentfulLabelId }: InputHelperTextProps) => {
  return (
    <motion.div key="helperText" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <p data-contentful-label-id={contentfulLabelId} className={multipleClassNames(styles.helperText, "body-s")}>
        {helperText}
      </p>
    </motion.div>
  );
};
